import{_ as a,o as i,c as t,a8 as s}from"./chunks/framework.ALLMRHJF.js";const m=JSON.parse('{"title":"Developer docs","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-document-repository/developer-docs.md","filePath":"content/plugins/bcew-document-repository/developer-docs.md"}'),o={name:"content/plugins/bcew-document-repository/developer-docs.md"};function n(d,e,l,c,r,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="developer-docs" tabindex="-1">Developer docs <a class="header-anchor" href="#developer-docs" aria-label="Permalink to “Developer docs”">​</a></h1><p>This guide describes the existing implementation and development setup for the Document Repository plugin.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><ul><li>Core orchestrator: <code>src/DocumentRepository.php</code></li><li>Configuration: <code>src/RepositoryConfig.php</code></li><li>Post type and taxonomies: <code>src/DocumentPostType.php</code></li><li>Uploads and attachment handling: <code>src/DocumentUploader.php</code></li><li>REST endpoints: <code>src/RestApiController.php</code></li><li>Metadata fields and caching: <code>src/DocumentMetadataManager.php</code></li><li>Admin assets and bootstrapping: <code>src/AdminUIManager.php</code></li><li>Settings toggle (enable/disable feature): <code>src/Settings.php</code></li></ul><p>Front-end/document behavior (search permalink override, title augmentation, publish after untrash) lives in <code>/bcew-document-repository.php</code>.</p><h2 id="admin-ui-implementation" tabindex="-1">Admin UI implementation <a class="header-anchor" href="#admin-ui-implementation" aria-label="Permalink to “Admin UI implementation”">​</a></h2><p>The admin app mounts under “Document Repository” and “Metadata Settings”. It supports PDF uploads, metadata editing, spreadsheet mode, bulk operations, status filters, and upload feedback.</p><ul><li>App entry: <code>/assets/js/apps/bcew-document-repository/index.js</code></li><li>Main app: <code>/assets/js/apps/bcew-document-repository/App.js</code></li><li>Styles: <code>/assets/scss/index.scss</code></li></ul><h2 id="metadata-implementation" tabindex="-1">Metadata implementation <a class="header-anchor" href="#metadata-implementation" aria-label="Permalink to “Metadata implementation”">​</a></h2><p>Metadata fields (text, date, taxonomy) are defined in Metadata Settings. Taxonomy fields automatically register a taxonomy with a <code>doc_</code> prefix.</p><ul><li>Fields: <code>Bcgov\\Bcew\\DocumentRepository\\DocumentMetadataManager::get_metadata_fields</code></li><li>Taxonomies: <code>Bcgov\\Bcew\\DocumentRepository\\DocumentPostType::register_metadata_taxonomies</code></li><li>Updated action: <code>bcgov_document_repository_metadata_fields_updated</code></li></ul><h2 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to “REST API”">​</a></h2><p>Namespace comes from <code>RepositoryConfig::get_api_namespace</code> in <code>src/RepositoryConfig.php</code> (default: <code>bcew-document-repository/v1</code>).</p><ul><li>GET <code>/{namespace}/documents</code> — the REST default is <code>publish</code>, but only <code>trash</code> selects a distinct result set. <code>trash</code> returns trashed documents; <code>publish</code>, <code>draft</code>, <code>any</code>, <code>all</code>, and other values return all non-trashed documents (<code>publish</code>, <code>draft</code>, <code>pending</code>, and <code>private</code>).</li><li>POST <code>/{namespace}/documents</code> — uploads a PDF and creates a document post with metadata.</li><li>GET <code>/{namespace}/documents/check-duplicate?search_name={filename}</code> — checks duplicate original filenames.</li><li>GET <code>/{namespace}/documents/{id}</code> — fetches a single document.</li></ul><p>See <code>src/RestApiController.php</code>. Requests use the <code>wp_rest</code> nonce and the capability from <code>RepositoryConfig::get_capability</code> (default: <code>upload_files</code>).</p><h2 id="file-storage-and-search-behavior" tabindex="-1">File storage and search behavior <a class="header-anchor" href="#file-storage-and-search-behavior" aria-label="Permalink to “File storage and search behavior”">​</a></h2><p>Files are stored under <code>/uploads/documents</code>; <code>DocumentUploader::custom_upload_dir</code> in <code>src/DocumentUploader.php</code> manages the upload directory. Document search permalinks link to the file URL, and titles include file type and size. This behavior is implemented in <code>bcew-document-repository.php</code>.</p><h2 id="requirements-and-development-setup" tabindex="-1">Requirements and development setup <a class="header-anchor" href="#requirements-and-development-setup" aria-label="Permalink to “Requirements and development setup”">​</a></h2><ul><li>WordPress 6.7+</li><li>PHP 7.4+</li><li>Composer</li><li>Node.js <code>^24.12.0</code></li><li>pnpm (the monorepo package manager)</li></ul><p>From the monorepo root:</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bcew-document-repository:composer-install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bcew-document-repository:build</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optional: start a local WordPress environment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bcew-document-repository:wp-env-start</span></span></code></pre></div><p>After these steps, activate the plugin from WordPress Admin (or use the wp-env site).</p>`,22)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
